def calculate_sum(n):
    # Initialize sum
    sum = 0

    # Loop through numbers from 1 to n
    for i in range(1, n + 1):
        # Check if number is divisible by 3 or 5
        if i % 3 == 0 or i % 5 == 0:
            # Add number to sum
            sum += i

    return sum

